.tkl{width:100%;max-width:460px;padding:0;overflow:hidden;display:flex;flex-direction:column}
.tkl-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px 16px 12px;border-bottom:1px solid var(--line)}
.tkl-t{margin-top:2px;font-size:16px;font-weight:600;color:var(--text)}
.tkl-head .seg b{margin-left:4px;font-family:var(--mono);font-size:10.5px;color:var(--muted)}
.tkl-list{display:flex;flex-direction:column}
.tkl-r{position:relative;display:grid;grid-template-columns:32px minmax(0,1fr) auto;gap:10px;padding:12px 16px;text-align:left;border-bottom:1px solid var(--line);transition:background-color .15s}
.tkl-r:hover{background:var(--bg)}
.tkl-r.on{background:var(--accent-bg)}
.tkl-r.on::before{content:"";position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--accent)}
.tkl-r .dz-av,.tkl-r .dz-av img{width:32px;height:32px}
.tkl-m{display:flex;flex-direction:column;gap:2px;min-width:0}
.tkl-n{display:flex;align-items:center;gap:6px;font-size:13px;font-weight:600;color:var(--text)}
.tkl-n .ms{font-size:13px;color:var(--muted)}
.tkl-s{font-size:13px;font-weight:500;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tkl-p{font-size:12.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tkl-side{display:flex;flex-direction:column;align-items:flex-end;gap:6px}
.tkl-time{font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted)}
.tkl-sla{display:inline-flex;align-items:center;gap:4px;padding:1px 6px;font-family:var(--mono);font-size:10.5px;font-weight:700;white-space:nowrap}
.tkl-sla.ok{color:#159a63;background:color-mix(in srgb,#159a63 10%,transparent)}
.tkl-sla.warn{color:#c2610f;background:color-mix(in srgb,#d98a00 12%,transparent)}
.tkl-sla.late{color:#e5484d;background:color-mix(in srgb,#e5484d 10%,transparent)}
.tkl-dot{position:absolute;left:8px;top:16px;width:6px;height:6px;border-radius:50%;background:var(--accent)}
[data-style="soft"] .tkl{border-radius:22px}
[data-style="soft"] .tkl-r{border-radius:0}
[data-style="soft"] .tkl-sla{border-radius:999px;font-family:var(--sans);font-weight:600}
[data-style="soft"] .tkl-time,[data-style="soft"] .tkl-head .seg b{font-family:var(--sans);font-weight:600}

