  };
  const row = (t, i, on) => `<button class="tkl-r ${on ? 'on' : ''}" data-i="${i}">${t[7] ? '<i class="tkl-dot"></i>' : ''}${avatar(t[0])}<span class="tkl-m"><span class="tkl-n">${t[0]}${ic(t[1],'sm')}</span><span class="tkl-s">${t[2]}</span><span class="tkl-p">${t[3]}</span></span><span class="tkl-side"><span class="tkl-time">${t[4]}</span><span class="tkl-sla ${t[5]}">${t[6]}</span></span></button>`;
  const show = (k, anim) => { list.innerHTML = T[k].map((t, i) => row(t, i, i === 0 && k === 'open')).join(''); hydrate(list);
    if (anim && !reduce) $$('.tkl-r', list).forEach((r, i) => r.animate([{ opacity:0, transform:'translateY(8px)' }, { opacity:1, transform:'none' }], { duration:360, delay:i * 45, easing:'cubic-bezier(.16,1,.3,1)', fill:'backwards' })); };
  show('open', false);
  list.addEventListener('click', e => { const r = e.target.closest('.tkl-r'); if (!r) return; $$('.tkl-r', list).forEach(x => x.classList.toggle('on', x === r)); const d = r.querySelector('.tkl-dot'); if (d) d.remove(); Sound.play('tab'); });
  segInit($('#tkl-seg'), v => { show(v, true); Sound.play('tab'); });
}
